public class ThrottleTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            int[] calls = {0};
            java.util.function.Function<Integer, Integer> f =
                    Throttle.onceOnly(x -> { calls[0]++; return x * 10; });
            check("first call computes", 30, f.apply(3));
            check("inner ran once", 1, calls[0]);
            check("repeat argument returns cached value", 30, f.apply(3));
            check("inner NOT called again for a repeat", 1, calls[0]);
            check("new argument computes", 50, f.apply(5));
            check("inner ran for the new argument", 2, calls[0]);
        } catch (RuntimeException e) {
            System.out.println("FAIL  onceOnly usage -- threw " + e.getClass().getSimpleName());
            failures += 6;
        }

        try {
            int[] calls = {0};
            java.util.function.Function<String, Integer> g =
                    Throttle.onceOnly(word -> { calls[0]++; return word.length(); });
            g.apply("abc");
            g.apply("abc");
            check("String keys cache by equals", 4, g.apply("wxyz"));
            check("two distinct String arguments -> two calls", 2, calls[0]);
        } catch (RuntimeException e) {
            System.out.println("FAIL  String caching -- threw " + e.getClass().getSimpleName());
            failures += 2;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

