public class Throttle {

    public static <T, R> java.util.function.Function<T, R> onceOnly(
            java.util.function.Function<T, R> inner) {
        java.util.Map<T, R> cache = new java.util.HashMap<>();
        return arg -> cache.computeIfAbsent(arg, inner);
    }
}
